		FedXLeftJoin leftJoin = new FedXLeftJoin(new LeftJoin(leftArg, rightArg), queryInfo);
		Value inputValue = Values.iri("urn:outside:input");
		Value foreignValue = Values.iri("urn:outside:foreign");
