	private static final class StubFederationEvaluationStrategy extends FederationEvaluationStrategy {
		private final Map<TupleExpr, QueryEvaluationStep> steps = new IdentityHashMap<>();
		private final boolean inheritMissingSteps;

		private StubFederationEvaluationStrategy(FederationContext federationContext) {
			this(federationContext, false);
		}

		private StubFederationEvaluationStrategy(FederationContext federationContext, boolean inheritMissingSteps) {
			super(federationContext);
			this.inheritMissingSteps = inheritMissingSteps;
		}

		private void register(TupleExpr expression, QueryEvaluationStep step) {
			steps.put(expression, step);
		}

		@Override
		public QueryEvaluationStep precompile(TupleExpr expression) {
			if (inheritMissingSteps && !steps.containsKey(expression)) {
				return super.precompile(expression);
			}
			return requiredStep(expression);
		}

		@Override
		public QueryEvaluationStep precompile(TupleExpr expression, QueryEvaluationContext context) {
			if (inheritMissingSteps && !steps.containsKey(expression)) {
				return super.precompile(expression, context);
			}
			return requiredStep(expression);
		}

		private QueryEvaluationStep requiredStep(TupleExpr expression) {
			QueryEvaluationStep step = steps.get(expression);
			if (step == null) {
				throw new AssertionError("unexpected compilation: " + expression);
			}
			return step;
		}
	}

	@Test
	public void scopedOptionalClosesLeftIterationWhenRightPreparationFails() throws Exception {
		FedXRepository repository = FedXFactory.newFederation().withMembers(new ArrayList<Endpoint>()).create();
		repository.init();
		try {
			FederationContext context = repository.getFederationContext();
			SingletonSet leftArg = new SingletonSet();
			SingletonSet rightArg = new SingletonSet();
			AtomicInteger openCount = new AtomicInteger();
			AtomicInteger closeCount = new AtomicInteger();
			QueryEvaluationException failure = new QueryEvaluationException("right preparation failed");
			FederationEvaluationStrategy strategy = new FederationEvaluationStrategy(context) {
				@Override
				public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext evaluationContext)
						throws QueryEvaluationException {
					if (expr == leftArg) {
						return bindings -> {
							openCount.incrementAndGet();
							return new CloseableIteratorIteration<>(Collections.emptyIterator()) {
								@Override
								protected void handleClose() {
									closeCount.incrementAndGet();
								}
							};
						};
					}
					if (expr == rightArg) {
						throw failure;
					}
					return super.precompile(expr, evaluationContext);
				}
			};
			QueryInfo queryInfo = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
			FedXLeftJoin leftJoin = new FedXLeftJoin(new LeftJoin(leftArg, rightArg), queryInfo);
			QueryEvaluationContext scoped = new ActiveGraphQueryEvaluationContext(
					new QueryEvaluationContext.Minimal(null),
					new QueryEvaluationContext.ActiveGraph(Values.iri("urn:active"), null));
			QueryEvaluationStep prepared = strategy.precompile(leftJoin, scoped);

			QueryEvaluationException thrown = Assertions.assertThrows(QueryEvaluationException.class,
					() -> prepared.evaluate(EmptyBindingSet.getInstance()));
			Assertions.assertSame(failure, thrown);
			Assertions.assertEquals(1, openCount.get());
			Assertions.assertEquals(1, closeCount.get());
		} finally {
			repository.shutDown();
		}
	}

